FamilyTree.person({"id":"bundervoet_joannes_1637","name":"Joannes Bundervoet","dates":"~1637 – 1 Dec 1707 Evergem","confidence":"sup","surname":"Bundervoet","family":"bundervoet","born":"~1637","order":"1637","died":"1 Dec 1707 Evergem","line":"bundervoet","father":"bundervoet_segerius_1615","mother":"vanhecke_joanna_1610","spouses":[{"id":"verbrugghe_joanna_1655","name":"Joanna Verbrugghe"}],"source":"paulderidder; glorieuxp; mjovdl","note":"Father of Joannes Bundervoet (1682). Parents Segerius Bundervoet x Joanna van Hecke."});
FamilyTree.person({"id":"bundervoet_joannes_1682","name":"Joannes Bundervoet","dates":"~1682 Evergem – 7 Nov 1760 Evergem","confidence":"sup","surname":"Bundervoet","family":"bundervoet","born":"~1682 Evergem","order":"1682","died":"7 Nov 1760 Evergem","line":"bundervoet","father":"bundervoet_joannes_1637","mother":"verbrugghe_joanna_1655","spouses":[{"id":"stockman_livina_1688","name":"Livina Stockman"},{"id":"dewilde_livina","name":"Livina De Wilde","detail":"m. ~1745"}],"source":"paulderidder; glorieuxp; dvandurme1; mjovdl","note":"Source detail: Geneanet trees paulderidder (Sosa 644), glorieuxp, dvandurme1, mjovdl (8+ Evergem trees agree)\n\nMarried twice — Livina Stockman (mother of Christoffel 1709 and of Pieter, who now has his own record as [[bundervoet_petrus_1727]]), then Livina De Wilde ~1745. That remarriage is what identifies him as the documented Joannes b.1682 and bridges our line into the deep Evergem Bundervoet trunk. Parents Joannes Bundervoet (1637-1707) x Joanna Verbrugghe."});
