FamilyTree.person({"id":"bundervoet_wilhelmina_1650","name":"Wilhelmina Bundervoet","dates":"b. ~1650","confidence":"sup","surname":"Bundervoet","family":"bundervoet","sex":"f","born":"~1650","order":"1650","line":"bundervoet","father":"bundervoet_livinus_1600","mother":"vanhecke_catharina_1620","source":"paulderidder","note":"Daughter of [[bundervoet_livinus_1600]] by his second wife [[vanhecke_catharina_1620]], and so a\nhalf-sister of [[bundervoet_segerius_1615]] — a blood relative of Renée and Léon through their\nshared father.\n\nThe paulderidder tree lists her under Segerius's half-siblings with a birth of about 1650 and\nnothing else. No act read."});
