FamilyTree.person({"id":"pickaut_livina_1687","name":"Livina Pickaut","dates":"17 Feb 1687 Lochristi – 22 Nov 1726 Lochristi","confidence":"sup","surname":"Pickaut","family":"pickaut","born":"17 Feb 1687 Lochristi","order":"1687-02-17","died":"22 Nov 1726 Lochristi","line":"paelinck","spouses":[{"id":"paelinck_adrianus_1690","name":"Adrianus Paelinck","detail":"m. Lochristi, 17 Jan 1711"}],"source":"stefpaelinck (Stef Paelinck)","note":"Died in 1726, the same year as her husband Adrianus; mother of Livinus (1718)."});
FamilyTree.person({"id":"pieren_leopoldus_1839","name":"Leopoldus Franciscus Pieren","dates":"b. 26 Nov 1839 Oostende","confidence":"sup","surname":"Pieren","family":"pieren","sex":"m","born":"26 Nov 1839 Oostende","order":"1839-11-26","occupation":"werkman (labourer)","line":"van-iseghem","spouses":[{"id":"huyghebaert_appolonia_1830","name":"Appolonia Joanna Huyghebaert","detail":"m. Oostende, 27 Oct 1868"}],"source":"West-Vlaamse Burgerlijke Stand — Huwelijken (marriage index), Rijksarchief Brugge/Kortrijk volunteers","note":"Second husband of [[huyghebaert_appolonia_1830]], widow of [[janssen_josephus_1820]]: Oostende, 27\nOctober 1868, act nr. 106 (RAB ID 580783, microfilm 1358593). Son of Petrus Gaspar Pieren\n(d. 30/04/1858 Oostende) × Catharina Dorothea Verlaecken (d. 04/08/1853 Oostende) — named\non the same act but not themselves given a record here, since nothing beyond this one\nindex row names them.\n\nThe act's remark notes the groom's paternal grandmother was named Anna Maria Pieren — a\ndetail with no further trail this pass."});
