FamilyTree.person({"id":"sabbe_judocus_1475","name":"Judocus (Joos) Sabbe","dates":"~1475 – 1534","confidence":"sup","surname":"Sabbe","family":"sabbe","born":"~1475","order":"1475","died":"1534","line":"bostyn-cappaert","father":"sabbe_gillis_1440","spouses":[{"id":"vandenberghe_nn","name":"NN Vandenberghe"}],"source":"isavdw — Rijksarchief-sourced, with scan links","note":"Born ~1475. Father of Petrus Sabbe (1504, Zwevegem). His own father is Gillis Sabbe (~1440), the deepest confirmed ancestor. Married an unnamed Vandenberghe."});
FamilyTree.person({"id":"sabbe_judocus_1667","name":"Judocus Sabbe","dates":"~1667 – 5 Feb 1737 Oostkamp","confidence":"sup","surname":"Sabbe","family":"sabbe","born":"~1667","order":"1667","died":"5 Feb 1737 Oostkamp","line":"bostyn-cappaert","father":"sabbe_simon_1627","mother":"rotsaert_joanna_1630","spouses":[{"id":"vannieuwenhuyse_anna_1676","name":"Anna Van Nieuwenhuyse","detail":"m. Oostkamp, 4 Aug 1700"}],"source":"isavdw — Rijksarchief-sourced, with scan links","note":"Father of Adriana Theresia Sabbe (1703). Married four times; farmer at Stuyvenberghe, Oostkamp. Parents Simon Sabbe (1627-1711) x Joanna Rotsaert.\n\nFRONTIER — three of the four marriages are unrecorded here. The one held is the **third**;\nisavdw gives no name, date or place for the first, second or fourth. Only Anna Van\nNieuwenhuyse is placed, so the spouse list below is not the sequence it looks like: it has\none entry of four, and any child found for him may belong to a wife this tree does not hold."});
FamilyTree.person({"id":"sabbe_petrus","name":"Petrus Sabbe","dates":"d. 31 Dec 1652 Oostkamp (Ruddervoorde)","confidence":"sup","surname":"Sabbe","family":"sabbe","died":"31 Dec 1652 Oostkamp (Ruddervoorde)","line":"bostyn-cappaert","father":"sabbe_willem","mother":"vandeputte_clara","spouses":[{"id":"vandenberghe_judoca_1594","name":"Judoca Vandenberghe","detail":"m. Oostkamp (Ruddervoorde), 11 Jun 1616"}],"source":"isavdw — Rijksarchief-sourced, with scan links","note":"Source detail: Geneanet isavdw (Rijksarchief aktes; Sosa 6760)\n\nAlso 'Schabbe'. Married Judoca Vandenberghe 1616; nine children incl. Simon Sabbe (1627). Witness at the wedding was his uncle Michiel Sabbe (b.1557). Parents Willem Sabbe x Clara Vande Putte. The Sabbe line runs back to Judocus 'Joos' Sabbe (~1475) around Harelbeke."});
