FamilyTree.person({"id":"stroobandt_adrianus_1746","name":"Adrianus Stroobandt","dates":"1746 – 1807 Oostkamp","confidence":"sup","surname":"Stroobandt","family":"stroobandt","born":"1746","order":"1746","died":"1807 Oostkamp","line":"bostyn-cappaert","father":"stroobandt_mauritius_1703","mother":"debaecke_barbara_1709","spouses":[{"id":"vanacker_anna_1749","name":"Anna Maria Van Acker","detail":"m. Oostkamp, 1768"}],"source":"isavdw — Rijksarchief-sourced, with scan links","note":"Father of Jacobus Stroobandt (1782). Married Anna Maria Van Acker 1768 Oostkamp."});
FamilyTree.person({"id":"stroobandt_florentinus_1811","name":"Florentinus Stroobandt","dates":"1811 – 4 Mar 1876 Oostkamp","confidence":"sup","surname":"Stroobandt","family":"stroobandt","born":"1811","order":"1811","died":"4 Mar 1876 Oostkamp","line":"bostyn-cappaert","father":"stroobandt_jacobus_1782","mother":"keirsebilck_joanna_1791","spouses":[{"id":"caeckaert_rosalia_1815","name":"Rosalia Caeckaert","detail":"m. Beernem, 29 Sep 1836"}],"source":"Death act of Florentinus Stroobandt, Oostkamp, 4 March 1876; kathrynann; Ancestry","note":"Father of Juliana Stroobandt (1839 Oedelem/Beernem). His own parents Jacobus Stroobandt × Joanna Keirsebilck are named in the same tree.\n\nDOCUMENTED DATE (July 2026). His death act gives **4 March 1876 at Oostkamp**, where the\ntree had only the year, and names [[caeckaert_rosalia_1815]] as his wife."});
