FamilyTree.person({"id":"stroobandt_jacobus_1782","name":"Jacobus Stroobandt","dates":"1 Sep 1782 Oostkamp – 24 Jun 1821 Oostkamp","confidence":"sup","surname":"Stroobandt","family":"stroobandt","born":"1 Sep 1782 Oostkamp","order":"1782-09-01","died":"24 Jun 1821 Oostkamp","occupation":"schoenmaker (shoemaker)","line":"bostyn-cappaert","father":"stroobandt_adrianus_1746","mother":"vanacker_anna_1749","spouses":[{"id":"demuynck_isabella_1782","name":"Isabella De Muynck"},{"id":"keirsebilck_joanna_1791","name":"Joanna Keirsebilck","detail":"m. Oostkamp, 24 Jul 1810"}],"source":"isavdw — Rijksarchief-sourced, with scan links","note":"Grandfather of Juliana Stroobandt, shoemaker. Married Isabella De Muynck (1782-1809), then Joanna Keirsebilck 24 Jul 1810. Parents Adrianus Stroobandt x Anna Maria Van Acker."});
FamilyTree.person({"id":"stroobandt_juliana_1839","name":"Juliana Stroobandt","dates":"1839 Beernem (Oedelem in another source) – 11 Feb 1921 Oostkamp","confidence":"sup","surname":"Stroobandt","family":"stroobandt","born":"1839 Beernem (Oedelem in another source)","order":"1839","died":"11 Feb 1921 Oostkamp","line":"bostyn-cappaert","father":"stroobandt_florentinus_1811","mother":"caeckaert_rosalia_1815","spouses":[{"id":"cappaert_carel_1835","name":"Carel Louis Cappaert","detail":"m. Oostkamp, 30 Sep 1863"}],"source":"isavdw — Rijksarchief-sourced, with scan links; kathrynann; 1960dirk (Dirk Teerlinck)","note":"Married Carel Cappaert 1863 Oostkamp. Birth given as 13 Sep 1839 Beernem (kathrynann) or 12 Sep 1839 Oedelem (1960dirk) — adjacent villages. One of eleven Stroobandt children."});
