FamilyTree.person({"id":"vanrenterghem_petrus_1500","name":"Petrus Van Renterghem","dates":"~1500 – before 1530","confidence":"sup","surname":"Van Renterghem","family":"vanrenterghem","born":"~1500","order":"1500","died":"before 1530","line":"bostyn-cappaert","spouses":[{"name":"(wife unrecorded)"}],"source":"isavdw — Rijksarchief-sourced, with scan links","note":"DEEPEST-TIER ANCESTOR — born ~1500, Oostkamp area. Father of Guillielmus Van Renterghem (~1530). Top of this line; no parents recorded."});
